import { defineConfig } from '@vscode/test-cli';
import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

import { userDataDir } from './scripts/lib/test-paths.ts';
import { testSettings } from './scripts/lib/test-settings.ts';

// Integration tests open the deterministic `branchy` fixture repository. It is
// generated by the npm scripts, not here: VS Code derives the workspace id from
// the folder's creation time, so recreating it would break the restart test.
const workspace = join(import.meta.dirname, 'out', 'fixtures', 'branchy');

const launchArgs = (label) => {
  const dir = userDataDir(label);
  mkdirSync(join(dir, 'User'), { recursive: true });
  writeFileSync(join(dir, 'User', 'settings.json'), JSON.stringify(testSettings, null, 2));
  return [
    `--user-data-dir=${dir}`,
    '--disable-extensions',
    '--disable-gpu',
    '--disable-workspace-trust',
    '--skip-welcome',
    '--skip-release-notes',
  ];
};

const base = {
  files: 'out/test/integration/**/*.test.cjs',
  workspaceFolder: workspace,
  mocha: { ui: 'bdd', timeout: 60_000 },
};

// npm run perf:e2e: the repository comes from STRATA_PERF_REPO.
const perf = {
  ...base,
  label: 'perf',
  version: 'stable',
  workspaceFolder: process.env.STRATA_PERF_REPO ?? workspace,
  files: 'out/test/perf/*.test.cjs',
  mocha: { ui: 'bdd', timeout: 600_000 },
  launchArgs: launchArgs('perf'),
};

// A folder holding several repositories (test/fixtures/workspaces.ts).
const multi = {
  ...base,
  files: 'out/test/multirepo/**/*.test.cjs',
  workspaceFolder: join(import.meta.dirname, 'out', 'fixtures', 'multi-repo'),
};

export default defineConfig([
  { ...base, label: 'stable', version: 'stable', launchArgs: launchArgs('stable') },
  { ...base, label: 'min', version: '1.90.0', launchArgs: launchArgs('min') },
  { ...multi, label: 'multi', version: 'stable', launchArgs: launchArgs('multi') },
  { ...multi, label: 'multi-min', version: '1.90.0', launchArgs: launchArgs('multi-min') },
  perf,
]);
